<?php require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/functions.php'; if(!empty($_SESSION['admin_id'])){header('Location:index.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=db()->prepare('SELECT id,password FROM usuarios WHERE usuario=? AND activo=1 LIMIT 1');$s->execute([trim($_POST['usuario']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['admin_id']=$u['id'];header('Location:index.php');exit;} $err='Usuario o contraseña incorrectos.';}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Admin · Snackliciosos</title><link rel="stylesheet" href="style.css?v=3"></head><body><main class="login"><h1>Snackliciosos</h1><h2>Administración</h2><?php if($err):?><div class="err"><?=h($err)?></div><?php endif;?><form method="post"><label>Usuario<input name="usuario" required autofocus></label><label>Contraseña<input name="password" type="password" required></label><button>ENTRAR</button></form></main></body></html>
